proc onCommitNeeded*(self: CompositorController,
                     handler: EventHandler[CompositorController, WinRtObject]
                    ): EventRegistrationToken {.discardable.} =
  ## Windows.UI.Composition.Core.CompositorController.add_CommitNeeded
