    proc shim(a0: pointer, a1: pointer) =
      handler(borrow[CompositorController](a0), borrow[WinRtObject](a1))
    let cb = newDelegate(IID_TypedEventHandler_2_CompositorController_Object,
                         shim, event = true)
    try:
      check it.vtbl.add_CommitNeeded(it, cb, result.addr), "CompositorController.add_CommitNeeded"
    finally:
      release(cb)

